const b = $input.first().json.body || $input.first().json;
const dryRun = b.dry_run === true || $env.DRY_RUN === 'true' || $env.DRY_RUN === true;
const live = b.divar_live_submit === true || $env.DIVAR_LIVE_SUBMIT === 'true';
const token = String(b.divar_post_token || '').trim();
const sku = String(b.sku || '');
const productId = b.product_id;

if (!token) {
  return [{ json: { result: 'SKIP', reason: 'no_divar_post_token', sku, product_id: productId } }];
}

const deleteEndpoint = `DELETE https://open-api.divar.ir/v1/open-platform/post/${token}`;
const requiredPermission = 'DELETE_USER_POST';

if (dryRun || !live) {
  return [{ json: { result: 'DRY_RUN_OK', action: 'would_close_divar', delete_endpoint: deleteEndpoint, permission: requiredPermission, sku, product_id: productId, post_token: token, manual_fallback: 'If API not enabled, close listing manually in Divar panel' } }];
}

return [{ json: { result: 'READY_FOR_LIVE', action: 'delete_post', delete_endpoint: deleteEndpoint, permission: requiredPermission, sku, post_token: token, note: 'Implement HTTP DELETE with x-api-key + Bearer in next phase after Divar approval' } }];
